from solution import prime_length

import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def ref_is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    d = 3
    while d * d <= n:
        if n % d == 0:
            return False
        d += 2
    return True


def ref_prime_length(s: str) -> bool:
    return ref_is_prime(len(s))


def small_primes_upto(limit: int):
    sieve = [True] * (limit + 1)
    if limit >= 0:
        sieve[0] = False
    if limit >= 1:
        sieve[1] = False
    for p in range(2, int(limit ** 0.5) + 1):
        if sieve[p]:
            for m in range(p * p, limit + 1, p):
                sieve[m] = False
    return [i for i, v in enumerate(sieve) if v]


PRIMES_100 = small_primes_upto(100)
COMPOSITES_100 = [i for i in range(0, 101) if i not in PRIMES_100]


def test_spec_example_hello():
    assert prime_length('Hello') is True


def test_spec_example_abcdcba():
    assert prime_length('abcdcba') is True


def test_spec_example_kittens():
    assert prime_length('kittens') is True


def test_spec_example_orange():
    assert prime_length('orange') is False


def test_empty_string_length_zero_not_prime():
    assert prime_length('') is False


def test_single_char_length_one_not_prime():
    assert prime_length('a') is False


def test_length_two_smallest_prime():
    assert prime_length('ab') is True


def test_length_three_is_prime():
    assert prime_length('abc') is True


def test_length_four_is_not_prime():
    assert prime_length('abcd') is False


def test_result_is_exact_bool():
    assert prime_length('Hello') is True
    assert prime_length('orange') is False
    assert type(prime_length('Hello')) is bool
    assert type(prime_length('orange')) is bool


@pytest.mark.parametrize("n", PRIMES_100)
def test_prime_lengths_return_true(n):
    s = 'x' * n
    assert prime_length(s) is True


@pytest.mark.parametrize("n", COMPOSITES_100)
def test_composite_lengths_return_false(n):
    s = 'x' * n
    assert prime_length(s) is False


@given(st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=80))
def test_equivalence_to_reference_model(s):
    assert prime_length(s) is ref_prime_length(s)


@given(st.integers(min_value=0, max_value=100))
def test_length_determines_result_not_content(n):
    # Metamorphic: any two strings of same length must agree,
    # and must match reference on length alone.
    s1 = 'a' * n
    s2 = 'Z q!9\n\t' * (n // 6 + 1)
    s2 = s2[:n]
    assert len(s2) == n
    assert prime_length(s1) == prime_length(s2)
    assert prime_length(s1) is ref_is_prime(n)


@given(st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=60))
def test_result_is_bool_for_arbitrary_string(s):
    r = prime_length(s)
    assert r is True or r is False
    assert type(r) is bool


@given(st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=60), st.text(alphabet=st.characters(blacklist_categories=('Cs',)), max_size=60))
def test_concatenation_length_consistency(a, b):
    # Lengths add; result must equal reference on total length.
    c = a + b
    assert len(c) == len(a) + len(b)
    assert prime_length(c) is ref_is_prime(len(a) + len(b))


@given(st.integers(min_value=0, max_value=50))
def test_appending_one_char_matches_reference_shift(n):
    s = 'm' * n
    t = s + 'z'
    assert prime_length(t) is ref_is_prime(n + 1)
    assert prime_length(s) is ref_is_prime(n)
